["subeventPrefix"] = "SPELL",
["use_absorbMode"] = true,
["custom"] = "function(allstates, event, unit)\n    if event == \"UNIT_ABSORB_AMOUNT_CHANGED\" or event == \"NAME_PLATE_UNIT_ADDED\" then\n        local guid = UnitGUID(unit)\n        if guid then \n            local npcID = select(6, strsplit(\"-\", guid))\n            if npcID and npcID == \"212827\" then\n                local absorb = UnitGetTotalAbsorbs(unit)\n                local state = allstates[guid]\n                if state then\n                    if absorb <= 0 then\n                        state.show = false\n                    else\n                        state.value = absorb\n                    end\n                    state.changed = true\n                else\n                    if absorb and absorb > 0 then\n                        allstates[guid] = {\n                            show = true,\n                            changed = true,\n                            progressType = \"static\",\n                            total = absorb,\n                            value = absorb,\n                        }\n                    end\n                end\n                return true\n            end\n        end\n    elseif event == \"NAME_PLATE_UNIT_REMOVED\" then\n        local guid = UnitGUID(unit)\n        if guid then\n            local state = allstates[guid]\n            if state then\n                state.show = false\n                state.changed = true\n                return true\n            end\n        end\n    end\nend",
