["custom"] = "function(allstates, event, isLogin, subevent, _, sourceGUID, _, _, _, _, _, _, _, spellId, _, _, _, amount)\n    \n    if event == \"WA_DELAYED_PLAYER_ENTERING_WORLD\" or event == \"STATUS\" or event == \"OPTIONS\" then\n        \n        if isLogin then\n            if aura_env.saved.state then aura_env.saved.state = nil end\n        end\n        \n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            \n            inversed = aura_env.config.inverse,\n            \n            TempestInternalStacks = aura_env.maxStacks,\n            \n            TempestStacks = aura_env.maxStacks,\n            TempestStacksInverse = 0,\n        }\n        \n        if aura_env.saved.state and (aura_env.saved.state.TempestInternalStacks ~= nil) then \n            allstates[\"\"].TempestInternalStacks = aura_env.saved.state.TempestInternalStacks\n            \n            allstates[\"\"].TempestStacks = aura_env.saved.state.TempestInternalStacks\n            if (allstates[\"\"].TempestStacks < 1) then allstates[\"\"].TempestStacks = 1 end\n            allstates[\"\"].TempestStacksInverse = aura_env.maxStacks - allstates[\"\"].TempestStacks\n        else\n            aura_env.saved.state = {}\n        end\n        \n        if allstates[\"\"].inversed then\n            allstates[\"\"].UniversalTempestStacks = allstates[\"\"].TempestStacksInverse\n        else\n            allstates[\"\"].UniversalTempestStacks = allstates[\"\"].TempestStacks\n        end\n        \n        return true\n        \n    elseif event == \"CHALLENGE_MODE_START\" or event == \"ENCOUNTER_START\" then\n        \n        if event == \"ENCOUNTER_START\" and sourceGUID == 5 then return end --groupSize, do not reset no m+ bosses\n        allstates[\"\"].changed = true\n        allstates[\"\"].TempestInternalStacks = aura_env.maxStacks\n        allstates[\"\"].TempestStacks = aura_env.maxStacks\n        allstates[\"\"].TempestStacksInverse = 0\n        \n        return true\n        \n    elseif (event == \"COMBAT_LOG_EVENT_UNFILTERED\" and sourceGUID == WeakAuras.myGUID) then\n        \n        if (subevent == \"SPELL_CAST_SUCCESS\" and aura_env.listOfSpenders[spellId]) then --Maelstrom Weapon Spenders\n            if spellId == 188443 and aura_env.arcCount ~= 0 and aura_env.tempestCount ~= 0 then --CL with Arc bug\n                aura_env.arcBugTime = GetTime()\n            end\n            \n            if (aura_env.mswCount ~= 0) then\n                allstates[\"\"].changed = true\n                aura_env.lastCast = GetTime()\n                \n                \n                allstates[\"\"].TempestInternalStacks = allstates[\"\"].TempestInternalStacks - aura_env.mswCount\n                if (allstates[\"\"].TempestInternalStacks < -9) then\n                    allstates[\"\"].TempestInternalStacks = -9\n                end\n                \n                allstates[\"\"].TempestStacks = allstates[\"\"].TempestInternalStacks\n                if (allstates[\"\"].TempestStacks < 1) then allstates[\"\"].TempestStacks = 1 end\n                allstates[\"\"].TempestStacksInverse = aura_env.maxStacks - allstates[\"\"].TempestStacks\n                \n                aura_env.saved.state.TempestInternalStacks = allstates[\"\"].TempestInternalStacks\n                \n                if allstates[\"\"].inversed then\n                    allstates[\"\"].UniversalTempestStacks = allstates[\"\"].TempestStacksInverse\n                else\n                    allstates[\"\"].UniversalTempestStacks = allstates[\"\"].TempestStacks\n                end\n                \n                return true\n            end\n            \n        elseif not (spellId == 344179 or spellId == 454015) then --MSW / Tempest\n            return\n            \n        elseif subevent == \"SPELL_AURA_REMOVED_DOSE\" and spellId == 454015 then\n            aura_env.tempestOneBuffRemoved = GetTime()\n            \n            return\n            \n        elseif ((subevent == \"SPELL_AURA_APPLIED\" or subevent == \"SPELL_AURA_REFRESH\" or subevent == \"SPELL_AURA_APPLIED_DOSE\") and (spellId == 454015)) then --Tempest\n            \n            if subevent == \"SPELL_AURA_APPLIED\" and aura_env.arcBugTime ~= 0 and ((GetTime() - aura_env.arcBugTime) <= 1) then\n                aura_env.arcBugTime = 0\n                return\n            end\n            \n            if (allstates[\"\"].TempestProcs == 0 and aura_env.nextTempestTime ~= 0 and ((GetTime() - aura_env.nextTempestTime) <= 1)) then --AS check\n                aura_env.nextTempestTime = 0\n                return\n            end\n            \n            if subevent == \"SPELL_AURA_REFRESH\" and aura_env.tempestOneBuffRemoved ~= 0 and ((GetTime() - aura_env.tempestOneBuffRemoved) <= 0.2) then\n                aura_env.tempestOneBuffRemoved = 0\n                return\n            end\n            \n            allstates[\"\"].changed = true\n            \n            allstates[\"\"].TempestInternalStacks = allstates[\"\"].TempestInternalStacks + aura_env.maxStacks;\n            if (allstates[\"\"].TempestInternalStacks > aura_env.maxStacks) then\n                allstates[\"\"].TempestInternalStacks = aura_env.maxStacks\n            end\n            \n            allstates[\"\"].TempestStacks = allstates[\"\"].TempestInternalStacks\n            allstates[\"\"].TempestStacksInverse = aura_env.maxStacks - allstates[\"\"].TempestStacks\n            aura_env.saved.state.TempestInternalStacks = allstates[\"\"].TempestInternalStacks\n            \n            if allstates[\"\"].inversed then\n                allstates[\"\"].UniversalTempestStacks = allstates[\"\"].TempestStacksInverse\n            else\n                allstates[\"\"].UniversalTempestStacks = allstates[\"\"].TempestStacks\n            end\n            \n            return true\n            \n        elseif (subevent == \"SPELL_AURA_REMOVED_DOSE\" and spellId == 344179 and (GetTime() < aura_env.lastCast + 0.5)) then -- If no talent for 10 MSW spend\n            \n            allstates[\"\"].changed = true\n            amount = amount or 0\n            aura_env.lastCast = 0\n            \n            allstates[\"\"].TempestInternalStacks = allstates[\"\"].TempestInternalStacks + amount\n            if (allstates[\"\"].TempestInternalStacks > aura_env.maxStacks) then\n                allstates[\"\"].TempestInternalStacks = aura_env.maxStacks\n            end\n            \n            allstates[\"\"].TempestStacks = allstates[\"\"].TempestInternalStacks\n            allstates[\"\"].TempestStacksInverse = aura_env.maxStacks - allstates[\"\"].TempestStacks\n            aura_env.saved.state.TempestInternalStacks = allstates[\"\"].TempestInternalStacks\n            \n            if allstates[\"\"].inversed then\n                allstates[\"\"].UniversalTempestStacks = allstates[\"\"].TempestStacksInverse\n            else\n                allstates[\"\"].UniversalTempestStacks = allstates[\"\"].TempestStacks\n            end\n            \n            return true\n            \n        end\n        \n    elseif event == \"TRIGGER\" then\n        local updatedTriggerNumber, updatedTriggerStates = isLogin, subevent\n        \n        local t = updatedTriggerStates[\"\"]\n        \n        if updatedTriggerNumber == 2 then\n            \n            allstates[\"\"].TempestProcs = t.totalStacks\n            if allstates[\"\"].TempestProcs == 0 then\n                aura_env.nextTempestTime = GetTime()\n            end\n            return true\n            \n        elseif updatedTriggerNumber == 3 then\n            aura_env.tempestCount = t.totalStacks\n        elseif updatedTriggerNumber == 4 then\n            aura_env.arcCount = t.matchCount\n        elseif updatedTriggerNumber == 5 then\n            aura_env.mswCount = t.totalStacks\n        end\n        \n        return\n    end\n    \nend",
["custom_hide"] = "custom",
