},
["custom"] = "function(allstates, event, unit, _, spellID)\n    if event == \"UNIT_SPELLCAST_START\" then\n        if spellID == 1224793 then\n            aura_env.counter = aura_env.counter + 1\n            local _, _, _, startC, endC  = UnitCastingInfo(unit)\n            local duration = (endC - startC) / 1000\n            local expirationTime = endC / 1000\n            allstates:Update(UnitGUID(unit), {\n                    progressType = \"timed\",\n                    duration = duration,\n                    expirationTime = expirationTime,\n                    even = aura_env.counter % 2 == 0,\n                    autoHide = true,\n            })\n        elseif spellID == 1236703 then\n            aura_env.counter = 0\n        end\n    elseif event == \"ENCOUNTER_START\" then\n        aura_env.counter = 0\n    end\nend",
