["custom"] = "local hasAddOn = C_AddOns.IsAddOnLoaded(\"SharedMedia_Causese\")\nif hasAddOn then\n    local voiceID\n    for _, voice in pairs(C_VoiceChat.GetTtsVoices()) do\n        if string.match(voice.name, \"Zira\") then\n            voiceID = voice.voiceID\n            break\n        end\n    end\n    if voiceID then\n        if aura_env.state and aura_env.state.count then\n            local mythic = aura_env.state.count == 2 or aura_env.state.count == 5 or aura_env.state.count == 6 or aura_env.state.count == 7\n            C_VoiceChat.SpeakText(voiceID, (mythic and \"Mythic\") or \"Heroic\", 1, 0.5, GetCVar(\"Sound_MasterVolume\")*100)\n        end\n    end\nend",
