["custom"] = "function(allstates, event, ...)\n    if event == \"UNIT_SPELLCAST_CHANNEL_STOP\" then\n        local unit, _, spellID = ...\n        if (spellID == 1242133 or spellID == 1245978) and (not aura_env.last or aura_env.last and GetTime()-aura_env.last > 1) then\n            aura_env.last = GetTime()\n            aura_env.counter = aura_env.counter + 1\n            if aura_env.counter <= 2 then\n                allstates:Update(\"\", {count = aura_env.counter})\n            else\n                allstates:Remove(\"\")\n            end\n        end\n    elseif event == \"ENCOUNTER_START\" then\n        aura_env.counter = 0\n        aura_env.last = nil\n        allstates:Update(\"\", {count = aura_env.counter})\n    end\nend",
