["icon"] = true,
["triggers"] = {
{
["trigger"] = {
["type"] = "spell",
["debuffType"] = "HELPFUL",
["subeventSuffix"] = "_CAST_START",
["use_exact_spellName"] = true,
["use_genericShowOn"] = true,
["genericShowOn"] = "showAlways",
["unit"] = "player",
["realSpellName"] = "Totemic Recall",
["use_spellName"] = true,
["spellIds"] = {
},
["subeventPrefix"] = "SPELL",
["event"] = "Cooldown Progress (Spell)",
["names"] = {
},
["use_track"] = true,
["spellName"] = 108285,
