["use_unit"] = true,
["realSpellName"] = 0,
["use_spellName"] = false,
["custom"] = "function(allstates, event, ...)\n    if event == \"ENCOUNTER_START\" then\n        aura_env.counter = 1\n        aura_env.flag = false\n        local timer = aura_env.timers[aura_env.counter]\n        allstates:Update(\"\", {\n                progressType = \"timed\",\n                duration = timer,\n                expirationTime = timer + GetTime(),\n                autoHide = true,\n        })\n        \n    elseif event == \"CAUSESE_PRIMAL_SPELLSTORM\" and ... and not aura_env.flag then\n        aura_env.counter = aura_env.counter + 1\n        local timer = aura_env.timers[aura_env.counter]\n        if not timer then\n            --chat gpt HAHA\n            local cycle = {14, 12, 15, 14, 15, 15}\n            local idx = ((aura_env.counter - #aura_env.timers - 1) % #cycle) + 1\n            timer = cycle[idx]\n        end\n        allstates:Update(\"\", {\n                progressType = \"timed\",\n                duration = timer,\n                expirationTime = timer + GetTime(),\n                autoHide = true,\n        })\n    elseif event == \"UNIT_SPELLCAST_SUCCEEDED\" then\n        local _, _, spellID = ...\n        if spellID == 1228059 then\n            aura_env.flag = true\n            allstates:Remove(\"\")\n        end\n    end\nend",
